"use client";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import "./glass-ai-kit.css";

// Sound comes from glass-sound.jsx when it is loaded and switched on
const gsnd = (n, o) => { const g = typeof window !== "undefined" && window.glassSound; return g ? g.play(n, o) : false; };

/* The parts around an AI answer: pick a model, start from a suggestion,
   write with files attached, watch research or an image come together,
   check the sources inline and act on the reply. None of them call a model;
   you pass in what yours returns. */

const reduce = () => typeof window !== "undefined" && window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const I = ({ d, size = 16, w = 1.8, fill }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill || "none"} stroke="currentColor" strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={d} /></svg>
);
const P = {
  check: "M5 12.5l4.5 4.5L19 7.5",
  x: "M6 6l12 12M18 6L6 18",
  down: "M6 9l6 6 6-6",
  left: "M15 6l-6 6 6 6",
  right: "M9 6l6 6-6 6",
  plus: "M12 5v14M5 12h14",
  up: "M12 19V5M5.5 11.5L12 5l6.5 6.5",
  spark: "M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8zM19 16l.7 2 2 .7-2 .7-.7 2-.7-2-2-.7 2-.7z",
  copy: "M9 9h10v10H9zM5 15V5h10",
  thumb: "M7 11v9H4.5A1.5 1.5 0 0 1 3 18.5v-6A1.5 1.5 0 0 1 4.5 11zM7 11l4-7.5c1.4 0 2.5 1.1 2.5 2.5V9h5a2 2 0 0 1 2 2.3l-1.2 7A2 2 0 0 1 17.3 20H7",
  retry: "M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7",
  speak: "M4 10v4h4l5 4V6L8 10zM16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12",
  file: "M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8zM14 3v5h5",
  image: "M4 5h16v14H4zM4 16l5-5 4 4 3-3 4 4M15.5 9.5h.01",
  globe: "M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM3 12h18M12 3c2.5 2.6 3.8 5.6 3.8 9s-1.3 6.4-3.8 9c-2.5-2.6-3.8-5.6-3.8-9S9.5 5.6 12 3z",
  mic: "M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3zM5 11a7 7 0 0 0 14 0M12 18v3",
  stop: "M7 7h10v10H7z",
};
const domainOf = (s) => s.domain || (s.href ? s.href.replace(/^https?:\/\/(www\.)?/, "").split("/")[0] : "");
/* A small round badge with the site's first letter, coloured from its name */
const hue = (s) => { let h = 0; for (const c of s || "") h = (h * 31 + c.charCodeAt(0)) % 360; return h; };
export function SiteBadge({ site, size = 18 }) {
  const name = (site || "?").replace(/^www\./, "");
  return <span className="gak-fav" style={{ "--h": hue(name), width: size, height: size, fontSize: size * 0.52 }} aria-hidden="true">{name[0].toUpperCase()}</span>;
}

/* ---------------------------------------------------------------------------
 * GlassModelPicker: a chip that opens a list of models. Each row has a name,
 * a one-line description and two small meters, so people pick by what a
 * model is good at rather than by its version number.
 * models    [{ id, name, description, speed: 1-3, smarts: 1-3, badge?, icon? }]
 * value, onChange
 * label     what the list is called (default "Model")
 * ------------------------------------------------------------------------- */
export function GlassModelPicker({ models = [], value, onChange, label = "Model", align = "start" }) {
  const [open, setOpen] = useState(false);
  const [hi, setHi] = useState(0);
  const box = useRef(null);
  const list = useRef(null);
  const id = useId();
  const cur = models.find((m) => m.id === value) || models[0];
  useEffect(() => {
    if (!open) return;
    setHi(Math.max(0, models.findIndex((m) => m.id === value)));
    const away = (e) => { if (box.current && !box.current.contains(e.target)) setOpen(false); };
    document.addEventListener("pointerdown", away);
    requestAnimationFrame(() => list.current && list.current.focus());
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);
  const pick = (m) => { onChange && onChange(m.id); setOpen(false); box.current && box.current.querySelector(".gmp-chip").focus(); };
  const key = (e) => {
    if (e.key === "ArrowDown") { e.preventDefault(); setHi((h) => (h + 1) % models.length); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setHi((h) => (h - 1 + models.length) % models.length); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(models[hi]); }
    else if (e.key === "Escape") { e.preventDefault(); setOpen(false); box.current.querySelector(".gmp-chip").focus(); }
  };
  const meter = (n, name) => <span className="gmp-meter" aria-label={`${name} ${n} of 3`}>{[1, 2, 3].map((k) => <i key={k} data-on={k <= n ? "" : undefined} />)}</span>;
  return (
    <div className="gmp" ref={box} data-open={open ? "" : undefined} data-align={align}>
      <button type="button" className="gmp-chip" aria-haspopup="listbox" aria-expanded={open} aria-controls={id} onClick={() => setOpen(!open)}>
        <span className="gmp-glyph" aria-hidden="true">{cur && cur.icon ? cur.icon : <I d={P.spark} size={13} w={1.8} />}</span>
        <span className="gmp-name">{cur ? cur.name : label}</span>
        <I d={P.down} size={14} w={2} />
      </button>
      {open && (
        <div className="gmp-pop" role="presentation">
          <div className="gmp-head"><span>{label}</span><span className="gmp-legend"><b>Speed</b><b>Smarts</b></span></div>
          <ul id={id} ref={list} className="gmp-list" role="listbox" tabIndex={-1} aria-label={label} aria-activedescendant={`${id}-${hi}`} onKeyDown={key}>
            {models.map((m, i) => (
              <li key={m.id} id={`${id}-${i}`} role="option" aria-selected={m.id === value} className="gmp-opt" data-hi={i === hi ? "" : undefined} style={{ "--i": i }}
                onPointerEnter={() => setHi(i)} onClick={() => pick(m)}>
                <span className="gmp-icon" aria-hidden="true">{m.icon || <I d={P.spark} size={15} />}</span>
                <span className="gmp-text">
                  <span className="gmp-row"><strong>{m.name}</strong>{m.badge && <em>{m.badge}</em>}</span>
                  <span className="gmp-desc">{m.description}</span>
                </span>
                <span className="gmp-meters">{meter(m.speed || 2, "Speed")}{meter(m.smarts || 2, "Smarts")}</span>
                <span className="gmp-tick" aria-hidden="true">{m.id === value && <I d={P.check} size={15} w={2.4} />}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * GlassStarters: the first screen of an assistant. A greeting, then a few
 * things to try. Picking one hands its prompt to you.
 * greeting    "Good morning, Elara"
 * sub         one line under it
 * items       [{ label, prompt?, icon? }]
 * onPick      (item) => void
 * ------------------------------------------------------------------------- */
export function GlassStarters({ greeting = "What can I help with?", sub, items = [], onPick, mark }) {
  const words = greeting.split(" ");
  return (
    <div className="gsta">
      {mark && <span className="gst-mark" aria-hidden="true">{mark}</span>}
      <h2 className="gst-hello" aria-label={greeting}>
        {words.map((w, i) => <span key={i} aria-hidden="true">{i > 0 && " "}<span style={{ "--i": i }}>{w}</span></span>)}
      </h2>
      {sub && <p className="gst-sub">{sub}</p>}
      <div className="gst-items">
        {items.map((it, i) => (
          <button key={it.label} type="button" className="gst-item" style={{ "--i": i + words.length }} onClick={() => onPick && onPick(it)}>
            {it.icon && <span className="gst-icon" aria-hidden="true">{it.icon}</span>}
            <span>{it.label}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * GlassCitedText: an answer with numbered sources inside the sentences.
 * Point at a number, or tap it, to see the page it came from.
 * parts     ["plain text", { cite: 1 }, " more text", { cite: [2, 3] }]
 * sources   [{ title, domain?, href?, snippet? }]   numbered from 1
 * footer    show the row of sources under the text (default true)
 * ------------------------------------------------------------------------- */
export function GlassCitedText({ parts = [], sources = [], footer = true, as: Tag = "p" }) {
  const [open, setOpen] = useState(null);
  const root = useRef(null);
  const via = useRef("mouse");
  useEffect(() => {
    if (open == null) return;
    const away = (e) => { if (root.current && !root.current.contains(e.target)) setOpen(null); };
    const esc = (e) => e.key === "Escape" && setOpen(null);
    document.addEventListener("pointerdown", away);
    document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("pointerdown", away); document.removeEventListener("keydown", esc); };
  }, [open]);
  const used = [...new Set(parts.flatMap((p) => (p && typeof p === "object" ? [].concat(p.cite) : [])))].filter((n) => sources[n - 1]);
  let k = 0;
  return (
    <div className="gct" ref={root}>
      <Tag className="gct-text">
        {parts.map((p, i) => {
          if (typeof p === "string") return <span key={i}>{p}</span>;
          const nums = [].concat(p.cite).filter((n) => sources[n - 1]);
          return nums.map((n) => {
            const s = sources[n - 1];
            const key = `${i}-${n}`;
            const isOpen = open === key;
            k += 1;
            return (
              <span key={key} className="gct-ref" data-open={isOpen ? "" : undefined}
                onPointerEnter={(e) => e.pointerType === "mouse" && setOpen(key)}
                onPointerLeave={(e) => e.pointerType === "mouse" && setOpen((o) => (o === key ? null : o))}>
                <button type="button" className="gct-n" aria-expanded={isOpen} aria-label={`Source ${n}: ${s.title}`}
                  onPointerDown={(e) => { via.current = e.pointerType; }}
                  onClick={() => setOpen(via.current === "mouse" ? key : isOpen ? null : key)}
                  onFocus={(e) => e.target.matches(":focus-visible") && setOpen(key)}>{n}</button>
                {isOpen && (
                  <span className="gct-card" role="tooltip">
                    <span className="gct-site"><SiteBadge site={domainOf(s)} size={16} />{domainOf(s)}</span>
                    {s.href ? <a className="gct-title" href={s.href} target="_blank" rel="noreferrer">{s.title}</a> : <strong className="gct-title">{s.title}</strong>}
                    {s.snippet && <span className="gct-snip">{s.snippet}</span>}
                  </span>
                )}
              </span>
            );
          });
        })}
      </Tag>
      {footer && used.length > 0 && (
        <div className="gct-foot">
          <span className="gct-stack" aria-hidden="true">{used.slice(0, 4).map((n) => <SiteBadge key={n} site={domainOf(sources[n - 1])} size={18} />)}</span>
          <span>{used.length} source{used.length > 1 ? "s" : ""}</span>
          <span className="gct-chips">{used.map((n) => <button key={n} type="button" className="gct-chip" onClick={() => setOpen(`foot-${n}`)} aria-label={`Source ${n}`}>{domainOf(sources[n - 1])}</button>)}</span>
          {typeof open === "string" && open.startsWith("foot-") && (() => {
            const s = sources[+open.slice(5) - 1];
            return <span className="gct-card gct-card-foot" role="tooltip"><span className="gct-site"><SiteBadge site={domainOf(s)} size={16} />{domainOf(s)}</span><strong className="gct-title">{s.title}</strong>{s.snippet && <span className="gct-snip">{s.snippet}</span>}</span>;
          })()}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * GlassMessageActions: the row under an answer. Copy, rate, read aloud,
 * try again, and step between versions when there is more than one.
 * text            what Copy copies
 * versions, version, onVersion(n)   e.g. 3 and 2 shows ‹ 2 / 3 ›
 * onRegenerate, onRate(up|down|null), onSpeak(playing)
 * ------------------------------------------------------------------------- */
export function GlassMessageActions({ text = "", versions = 1, version = 1, onVersion, onRegenerate, onRate, onSpeak, busy = false }) {
  const [copied, setCopied] = useState(false);
  const [rate, setRate] = useState(null);
  const [speaking, setSpeaking] = useState(false);
  const [spin, setSpin] = useState(0);
  useEffect(() => { if (!speaking) return; const t = setTimeout(() => { setSpeaking(false); onSpeak && onSpeak(false); }, Math.min(9000, 1200 + text.length * 40)); return () => clearTimeout(t); }, [speaking]);
  const copy = async () => { try { await navigator.clipboard.writeText(text); } catch (e) {} setCopied(true); setTimeout(() => setCopied(false), 1500); };
  const doRate = (v) => { const n = rate === v ? null : v; setRate(n); onRate && onRate(n); };
  const tip = (label, el) => <span className="gma-tip-wrap">{el}<span className="gma-tip" aria-hidden="true">{label}</span></span>;
  return (
    <div className="gma" role="toolbar" aria-label="Answer actions" data-busy={busy ? "" : undefined}>
      {tip(copied ? "Copied" : "Copy", <button type="button" className="gma-btn" aria-label={copied ? "Copied" : "Copy"} data-done={copied ? "" : undefined} onClick={copy}><I d={copied ? P.check : P.copy} size={16} w={copied ? 2.4 : 1.8} /></button>)}
      {tip("Good answer", <button type="button" className="gma-btn" aria-label="Good answer" aria-pressed={rate === "up"} onClick={() => doRate("up")}><I d={P.thumb} fill={rate === "up" ? "currentColor" : undefined} /></button>)}
      {tip("Bad answer", <button type="button" className="gma-btn gma-down" aria-label="Bad answer" aria-pressed={rate === "down"} onClick={() => doRate("down")}><I d={P.thumb} fill={rate === "down" ? "currentColor" : undefined} /></button>)}
      {tip(speaking ? "Stop" : "Read aloud", <button type="button" className="gma-btn" aria-label={speaking ? "Stop reading" : "Read aloud"} aria-pressed={speaking} onClick={() => { setSpeaking(!speaking); onSpeak && onSpeak(!speaking); }}>
        {speaking ? <span className="gma-wave" aria-hidden="true"><i /><i /><i /><i /></span> : <I d={P.speak} />}
      </button>)}
      {onRegenerate && tip("Try again", <button type="button" className="gma-btn" aria-label="Try again" disabled={busy} onClick={() => { setSpin((s) => s + 1); onRegenerate(); }}><span className="gma-spin" key={spin}><I d={P.retry} /></span></button>)}
      {versions > 1 && (
        <span className="gma-ver" role="group" aria-label="Versions">
          <button type="button" className="gma-btn gma-sm" aria-label="Previous version" disabled={version <= 1} onClick={() => onVersion && onVersion(version - 1)}><I d={P.left} size={14} w={2.2} /></button>
          <span className="gma-count" aria-live="polite"><b key={version}>{version}</b> / {versions}</span>
          <button type="button" className="gma-btn gma-sm" aria-label="Next version" disabled={version >= versions} onClick={() => onVersion && onVersion(version + 1)}><I d={P.right} size={14} w={2.2} /></button>
        </span>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * GlassImageGen: an image that develops while your model makes it. It starts
 * as soft dots of colour and sharpens as progress climbs.
 * progress   0 to 1, from your model; leave it out to fake a gentle climb
 * children   the finished image (an <img>, or anything)
 * prompt     shown under it
 * ratio      "1 / 1", "4 / 5", "16 / 9"
 * onCancel, onDone
 * ------------------------------------------------------------------------- */
export function GlassImageGen({ progress, children, prompt, ratio = "4 / 5", onCancel, onDone, duration = 6000, run = 0 }) {
  const [fake, setFake] = useState(progress == null ? 0 : progress);
  useEffect(() => {
    if (progress != null) return;
    if (reduce()) { setFake(1); return; }
    setFake(0);
    const t0 = performance.now();
    let raf;
    const tick = (t) => {
      const x = Math.min(1, (t - t0) / duration);
      setFake(1 - Math.pow(1 - x, 2.2));
      if (x < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [progress, run, duration]);
  const p = progress == null ? fake : Math.max(0, Math.min(1, progress));
  const done = p >= 1;
  useEffect(() => { if (done && onDone) onDone(); }, [done]);
  return (
    <figure className="gig" data-done={done ? "" : undefined} style={{ "--p": p, aspectRatio: ratio }}>
      <div className="gig-art">{children}</div>
      <div className="gig-dots" aria-hidden="true" />
      <div className="gig-shine" aria-hidden="true" />
      {!done && (
        <div className="gig-hud">
          <span className="gig-ring" role="progressbar" aria-label="Making the image" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(p * 100)}><b>{Math.round(p * 100)}%</b></span>
          {onCancel && <button type="button" className="gig-cancel" onClick={onCancel} aria-label="Stop"><I d={P.x} size={14} w={2.2} /></button>}
        </div>
      )}
      {prompt && <figcaption className="gig-cap">{done ? prompt : p < 0.35 ? "Sketching shapes…" : p < 0.75 ? "Adding colour and light…" : "Sharpening details…"}</figcaption>}
    </figure>
  );
}

/* ---------------------------------------------------------------------------
 * GlassResearch: deep research you can watch. A plan, a live count of the
 * pages read, the page it is reading now, and a stop button. When it ends it
 * folds into a small summary card.
 * title
 * steps     [{ label, status: "todo" | "active" | "done" }]
 * sources   [{ title, domain }]    the pages read so far
 * reading   the page being read now (a source)
 * status    "running" | "done" | "stopped"
 * elapsed   "3m 12s"
 * onStop, onOpen
 * ------------------------------------------------------------------------- */
export function GlassResearch({ title = "Research", steps = [], sources = [], reading, status = "running", elapsed, onStop, onOpen }) {
  const done = steps.filter((s) => s.status === "done").length;
  const p = steps.length ? (done + (steps.some((s) => s.status === "active") ? 0.5 : 0)) / steps.length : 0;
  if (status === "done") {
    return (
      <button type="button" className="grs grs-done" onClick={onOpen}>
        <span className="grs-art" aria-hidden="true"><I d={P.file} size={20} /></span>
        <span className="grs-sum">
          <strong>{title}</strong>
          <span><span className="grs-stack" aria-hidden="true">{sources.slice(0, 3).map((s, i) => <SiteBadge key={i} site={s.domain} size={16} />)}</span>{sources.length} sources · {steps.length} steps{elapsed ? " · " + elapsed : ""}</span>
        </span>
        <span className="grs-open">Open</span>
      </button>
    );
  }
  return (
    <section className="grs" aria-label={title} data-status={status}>
      <header className="grs-head">
        <span className="grs-badge"><I d={P.globe} size={14} />Deep research</span>
        <strong className="grs-title">{title}</strong>
        {status === "running" && onStop && <button type="button" className="grs-stop" onClick={onStop} aria-label="Stop research"><I d={P.stop} size={12} w={0} fill="currentColor" /></button>}
      </header>
      <ol className="grs-steps">
        {steps.map((s, i) => (
          <li key={i} data-s={s.status} style={{ "--i": i }}>
            <span className="grs-dot" aria-hidden="true">{s.status === "done" ? <I d={P.check} size={11} w={3} /> : s.status === "active" ? <i /> : null}</span>
            <span>{s.label}</span>
          </li>
        ))}
      </ol>
      <div className="grs-live" aria-live="polite">
        <span className="grs-stack" aria-hidden="true">{sources.slice(-5).map((s, i) => <SiteBadge key={sources.length - 5 + i} site={s.domain} size={20} />)}</span>
        <span className="grs-count"><b key={sources.length}>{sources.length}</b> {sources.length === 1 ? "page" : "pages"} read</span>
        {reading && status === "running" && <span className="grs-now" key={reading.title}>Reading <em>{reading.title}</em></span>}
        {status === "stopped" && <span className="grs-now">Stopped. Showing what it found so far.</span>}
      </div>
      <div className="grs-bar" aria-hidden="true"><i style={{ width: `${Math.max(4, p * 100)}%` }} /></div>
    </section>
  );
}

/* ---------------------------------------------------------------------------
 * GlassComposer: the message box, grown up. Files sit above the text as
 * chips, a mode (like Research) shows as a removable tag, and the plus menu
 * adds files or turns modes on.
 * value, onChange, onSend(text)
 * attachments    [{ id, name, size?, kind: "file" | "image", preview?, progress? }]
 * onAttach()     the plus menu's "Add files"; you open the file picker
 * onRemove(id)
 * modes          [{ id, label, icon? }]   mode, onMode(id | null)
 * right          elements before the send button (a model picker, a mic)
 * busy, onStop
 * ------------------------------------------------------------------------- */
export function GlassComposer({ value = "", onChange, onSend, attachments = [], onAttach, onRemove, modes = [], mode, onMode, right, busy = false, onStop, placeholder = "Ask anything" }) {
  const [menu, setMenu] = useState(false);
  const ta = useRef(null);
  const box = useRef(null);
  useEffect(() => { const el = ta.current; if (!el) return; el.style.height = "auto"; el.style.height = Math.min(el.scrollHeight, 200) + "px"; }, [value]);
  useEffect(() => {
    if (!menu) return;
    const away = (e) => { if (box.current && !box.current.contains(e.target)) setMenu(false); };
    const esc = (e) => e.key === "Escape" && setMenu(false);
    document.addEventListener("pointerdown", away); document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("pointerdown", away); document.removeEventListener("keydown", esc); };
  }, [menu]);
  const m = modes.find((x) => x.id === mode);
  const uploading = attachments.some((a) => a.progress != null && a.progress < 1);
  const can = value.trim() && !busy && !uploading;
  const send = () => { if (can && onSend) { gsnd("send"); onSend(value.trim()); } };
  return (
    <div className="gkc" ref={box} data-busy={busy ? "" : undefined}>
      {attachments.length > 0 && (
        <div className="gkc-files">
          {attachments.map((a) => (
            <span key={a.id} className="gkc-file" data-kind={a.kind || "file"}>
              {a.kind === "image" ? <span className="gkc-thumb" style={{ background: a.preview }} aria-hidden="true" /> : <span className="gkc-ficon" aria-hidden="true"><I d={P.file} size={16} /></span>}
              <span className="gkc-fname"><b>{a.name}</b>{a.size && <em>{a.progress != null && a.progress < 1 ? `Uploading ${Math.round(a.progress * 100)}%` : a.size}</em>}</span>
              {a.progress != null && a.progress < 1 && <span className="gkc-up" style={{ "--p": a.progress }} aria-hidden="true" />}
              {onRemove && <button type="button" className="gkc-x" aria-label={"Remove " + a.name} onClick={() => onRemove(a.id)}><I d={P.x} size={11} w={2.6} /></button>}
            </span>
          ))}
        </div>
      )}
      <textarea ref={ta} className="gkc-input" rows={1} value={value} placeholder={m ? `${m.label}: ${placeholder.toLowerCase()}` : placeholder} aria-label={placeholder}
        onChange={(e) => onChange && onChange(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); send(); } }} />
      <div className="gkc-bar">
        <span className="gkc-plus-wrap">
          <button type="button" className="gkc-round" aria-label="Add" aria-expanded={menu} aria-haspopup="menu" onClick={() => setMenu(!menu)} data-on={menu ? "" : undefined}><I d={P.plus} size={18} w={2} /></button>
          {menu && (
            <div className="gkc-menu" role="menu">
              {onAttach && <button type="button" role="menuitem" onClick={() => { setMenu(false); onAttach(); }}><I d={P.file} />Add photos and files</button>}
              {modes.map((x) => (
                <button key={x.id} type="button" role="menuitemcheckbox" aria-checked={mode === x.id} onClick={() => { setMenu(false); onMode && onMode(mode === x.id ? null : x.id); }}>
                  {x.icon || <I d={P.spark} />}{x.label}<span className="gkc-switch" data-on={mode === x.id ? "" : undefined} aria-hidden="true" />
                </button>
              ))}
            </div>
          )}
        </span>
        {m && <span className="gkc-mode">{m.icon || <I d={P.spark} size={14} />}{m.label}<button type="button" aria-label={"Turn off " + m.label} onClick={() => onMode && onMode(null)}><I d={P.x} size={11} w={2.6} /></button></span>}
        <span className="gkc-grow" />
        {right}
        {busy
          ? <button type="button" className="gkc-send" data-stop="" aria-label="Stop" onClick={onStop}><I d={P.stop} size={12} w={0} fill="currentColor" /></button>
          : <button type="button" className="gkc-send" aria-label="Send" disabled={!can} onClick={send}><I d={P.up} size={18} w={2.2} /></button>}
      </div>
    </div>
  );
}

/* AI kit: model picker, starters, cited text, message actions, image
   generation, research and composer. Colours come from the theme tokens. */
.gmp, .gsta, .gct, .gma, .gig, .grs, .gkc {
  --gk-c: var(--glass-tint, #6b5cff);
  --gk-s: var(--q-surface, #fff);
  --gk-line: rgb(var(--glass-shadow) / 0.1);
  --gk-mute: rgb(var(--glass-shadow) / 0.58);
  --gk-soft: rgb(var(--glass-shadow) / 0.06);
  --gk-spring: cubic-bezier(0.3, 1.45, 0.5, 1);
  --gk-out: cubic-bezier(0.2, 0.8, 0.2, 1);
}
:root[data-glass-mode="dark"] :is(.gmp, .gsta, .gct, .gma, .gig, .grs, .gkc) { --gk-s: #1c1c20; }
[data-glass-tint="frost"] :is(.gmp, .gsta, .gct, .gma, .gig, .grs, .gkc) { --gk-c: var(--frost-accent, #4b5565); }
@keyframes gk-rise { from { opacity: 0; transform: translateY(8px); filter: blur(4px); } }
@keyframes gk-pop { from { scale: 0.6; opacity: 0; } }
@keyframes gk-spin { to { transform: rotate(360deg); } }

/* Site badge: a round letter in a colour from the site's name */
.gak-fav { display: inline-grid; place-items: center; flex: none; border-radius: 50%; font-weight: 700; line-height: 1; color: #fff; background: hsl(var(--h) 55% 46%); box-shadow: 0 0 0 1.5px var(--gk-s, #fff); }

/* ---------- Model picker ---------- */
.gmp { position: relative; display: inline-flex; }
.gmp-chip { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px 0 6px; border: 0; border-radius: 99px; font: 500 13.5px var(--font, inherit); color: var(--glass-fg); background: var(--gk-soft); cursor: pointer; transition: background-color 0.2s, scale 0.35s var(--gk-spring); }
.gmp-chip:hover, .gmp[data-open] .gmp-chip { background: rgb(var(--glass-shadow) / 0.1); }
.gmp-chip:active { scale: 0.95; }
.gmp-chip > svg:last-child { color: var(--gk-mute); transition: rotate 0.3s var(--gk-out); }
.gmp[data-open] .gmp-chip > svg:last-child { rotate: 180deg; }
.gmp-glyph { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: var(--glass-on-tint, #fff); background: var(--gk-c); }
.gmp-pop { position: absolute; z-index: 40; bottom: calc(100% + 8px); left: 0; width: min(380px, calc(100vw - 32px)); padding: 6px; border-radius: 18px; color: var(--glass-fg); background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 24px 50px -20px rgb(0 0 0 / 0.35); transform-origin: bottom left; animation: gmp-in 0.32s var(--gk-spring); }
.gmp[data-align="end"] .gmp-pop { left: auto; right: 0; transform-origin: bottom right; }
.gmp[data-below] .gmp-pop { bottom: auto; top: calc(100% + 8px); transform-origin: top left; }
@keyframes gmp-in { from { opacity: 0; scale: 0.92; translate: 0 6px; } }
.gmp-head { display: flex; justify-content: space-between; align-items: center; padding: 6px 10px 6px; font-size: 12px; font-weight: 600; color: var(--gk-mute); }
.gmp-legend { display: inline-flex; gap: 10px; margin-right: 34px; }
.gmp-legend b { width: 30px; font-weight: 500; font-size: 10.5px; text-align: center; }
.gmp-list { margin: 0; padding: 0; list-style: none; outline: none; }
.gmp-opt { display: flex; align-items: center; gap: 12px; padding: 10px; border-radius: 12px; cursor: pointer; animation: gk-rise 0.35s calc(var(--i) * 35ms) var(--gk-out) backwards; transition: background-color 0.15s; }
.gmp-opt[data-hi] { background: var(--gk-soft); }
.gmp-icon { display: grid; place-items: center; flex: none; width: 34px; height: 34px; border-radius: 10px; color: var(--gk-c); background: color-mix(in srgb, var(--gk-c) 12%, transparent); }
.gmp-text { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 0; }
.gmp-row { display: flex; align-items: center; gap: 6px; font-size: 14px; }
.gmp-row strong { font-weight: 600; }
.gmp-row em { padding: 1px 6px; border-radius: 99px; font-style: normal; font-size: 10.5px; font-weight: 600; color: var(--gk-c); background: color-mix(in srgb, var(--gk-c) 13%, transparent); }
.gmp-desc { font-size: 12.5px; line-height: 1.35; color: var(--gk-mute); }
.gmp-meters { display: inline-flex; gap: 10px; }
.gmp-meter { display: inline-flex; gap: 2px; width: 30px; justify-content: center; }
.gmp-meter i { width: 6px; height: 10px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.12); }
.gmp-meter i[data-on] { background: var(--gk-c); }
.gmp-tick { display: grid; place-items: center; width: 22px; color: var(--gk-c); }
.gmp-tick svg { animation: gk-pop 0.35s var(--gk-spring); }
[data-glass-tint="ink"] :is(.gmp-icon, .gmp-tick, .gmp-row em) { color: var(--glass-fg); }
[data-glass-tint="ink"] .gmp-meter i[data-on] { background: var(--glass-fg); }
@media (max-width: 480px) { .gmp-meters, .gmp-legend { display: none; } }

/* ---------- Starters ---------- */
.gsta { display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center; }
.gst-mark { display: grid; place-items: center; margin-bottom: 6px; animation: gk-pop 0.6s var(--gk-spring) backwards; }
.gst-hello { margin: 0; font-size: clamp(24px, 4.4vw, 34px); font-weight: 600; letter-spacing: -0.035em; line-height: 1.1; color: var(--glass-fg); text-wrap: balance; }
.gst-hello span span { display: inline-block; animation: gk-rise 0.6s calc(var(--i) * 70ms) var(--gk-out) backwards; }
.gst-sub { margin: 0; font-size: 15px; color: var(--gk-mute); animation: gk-rise 0.6s 0.25s var(--gk-out) backwards; }
.gst-items { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 560px; margin-top: 14px; }
.gst-item { display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 15px 0 12px; border: 0; border-radius: 99px; font: 500 14px var(--font, inherit); color: var(--glass-fg); background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 2px 6px -3px rgb(0 0 0 / 0.12); cursor: pointer; animation: gk-rise 0.5s calc(var(--i) * 55ms) var(--gk-out) backwards; transition: translate 0.35s var(--gk-spring), box-shadow 0.2s; }
.gst-item:hover { translate: 0 -2px; box-shadow: 0 0 0 1px rgb(var(--glass-shadow) / 0.16), 0 10px 20px -12px rgb(0 0 0 / 0.3); }
.gst-item:active { translate: 0; scale: 0.97; }
.gst-icon { display: grid; place-items: center; color: var(--gk-c); }
[data-glass-tint="ink"] .gst-icon { color: var(--glass-fg); }
.gst-icon svg { width: 16px; height: 16px; }

/* ---------- Cited text ---------- */
.gct { position: relative; display: flex; flex-direction: column; gap: 12px; color: var(--glass-fg); }
.gct-text { margin: 0; font-size: 15.5px; line-height: 1.7; }
.gct-ref { position: relative; display: inline; }
.gct-n { display: inline-grid; place-items: center; min-width: 18px; height: 18px; margin: 0 1px 0 3px; padding: 0 5px; border: 0; border-radius: 6px; vertical-align: 2px; font: 600 11px var(--font, inherit); font-variant-numeric: tabular-nums; color: var(--gk-mute); background: var(--gk-soft); cursor: pointer; transition: background-color 0.15s, color 0.15s, scale 0.3s var(--gk-spring); }
.gct-n:hover, .gct-ref[data-open] .gct-n { color: var(--glass-on-tint, #fff); background: var(--gk-c); }
.gct-n:active { scale: 0.9; }
.gct-card { position: absolute; z-index: 30; left: 50%; bottom: calc(100% + 8px); display: flex; flex-direction: column; gap: 4px; width: min(280px, 78vw); padding: 12px 14px; border-radius: 14px; text-align: left; font-size: 13px; line-height: 1.45; color: var(--glass-fg); background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 18px 40px -16px rgb(0 0 0 / 0.35); transform: translateX(-50%); transform-origin: bottom center; animation: gct-in 0.28s var(--gk-spring); }
@keyframes gct-in { from { opacity: 0; scale: 0.9; translate: 0 4px; } }
.gct-site { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--gk-mute); }
.gct-title { font-weight: 600; font-size: 13.5px; color: inherit; text-decoration: none; }
a.gct-title:hover { text-decoration: underline; }
.gct-snip { color: var(--gk-mute); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.gct-foot { position: relative; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 12.5px; color: var(--gk-mute); }
.gct-stack, .grs-stack { display: inline-flex; }
.gct-stack .gak-fav + .gak-fav, .grs-stack .gak-fav + .gak-fav { margin-left: -6px; }
.gct-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.gct-chip { height: 24px; padding: 0 9px; border: 0; border-radius: 99px; font: 500 12px var(--font, inherit); color: var(--gk-mute); background: var(--gk-soft); cursor: pointer; }
.gct-chip:hover { color: var(--glass-fg); }
.gct-card-foot { left: 0; transform: none; transform-origin: bottom left; }

/* ---------- Message actions ---------- */
.gma { display: flex; align-items: center; gap: 2px; color: var(--gk-mute); }
.gma-tip-wrap { position: relative; display: inline-flex; }
.gma-btn { display: grid; place-items: center; width: 32px; height: 32px; padding: 0; border: 0; border-radius: 9px; color: inherit; background: none; cursor: pointer; transition: background-color 0.15s, color 0.15s, scale 0.35s var(--gk-spring); }
.gma-btn:hover:not(:disabled) { color: var(--glass-fg); background: var(--gk-soft); }
.gma-btn:active:not(:disabled) { scale: 0.88; }
.gma-btn:disabled { opacity: 0.35; cursor: default; }
.gma-btn[aria-pressed="true"] { color: var(--glass-fg); }
.gma-btn[aria-pressed="true"] svg { animation: gma-bump 0.45s var(--gk-spring); }
.gma-btn[data-done] { color: #16a34a; }
.gma-btn[data-done] svg { animation: gk-pop 0.35s var(--gk-spring); }
.gma-down svg { rotate: 180deg; }
@keyframes gma-bump { 40% { scale: 1.3; rotate: -12deg; } }
.gma-down[aria-pressed="true"] svg { animation-name: gma-bump-down; }
@keyframes gma-bump-down { 40% { scale: 1.3; rotate: 168deg; } }
.gma-spin { display: grid; animation: gma-turn 0.6s var(--gk-out); }
.gma-spin:first-child:not(:only-child) { animation: none; }
@keyframes gma-turn { from { rotate: -300deg; } }
.gma-wave { display: flex; align-items: center; gap: 2px; height: 14px; color: var(--gk-c); }
.gma-wave i { width: 2.5px; height: 100%; border-radius: 2px; background: currentColor; animation: gma-wave 0.8s ease-in-out infinite; }
.gma-wave i:nth-child(2) { animation-delay: 0.12s; } .gma-wave i:nth-child(3) { animation-delay: 0.24s; } .gma-wave i:nth-child(4) { animation-delay: 0.36s; }
@keyframes gma-wave { 0%, 100% { transform: scaleY(0.3); } 50% { transform: scaleY(1); } }
.gma-tip { position: absolute; bottom: calc(100% + 6px); left: 50%; padding: 4px 8px; border-radius: 7px; white-space: nowrap; font-size: 11.5px; font-weight: 500; color: #fff; background: #111114; transform: translateX(-50%); opacity: 0; translate: 0 3px; pointer-events: none; transition: opacity 0.15s, translate 0.2s var(--gk-out); }
.gma-tip-wrap:hover .gma-tip, .gma-tip-wrap:focus-within .gma-tip { opacity: 1; translate: 0; transition-delay: 0.35s; }
@media (hover: none) { .gma-tip { display: none; } }
.gma-ver { display: inline-flex; align-items: center; gap: 0; margin-left: 6px; padding-left: 8px; border-left: 1px solid var(--gk-line); }
.gma-sm { width: 26px; height: 26px; }
.gma-count { min-width: 38px; text-align: center; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.gma-count b { display: inline-block; font-weight: 600; color: var(--glass-fg); animation: gk-rise 0.3s var(--gk-out); }

/* ---------- Image generation ---------- */
.gig { --p: 0; position: relative; overflow: hidden; isolation: isolate; width: 100%; margin: 0; border-radius: 20px; background: #101014; box-shadow: 0 0 0 1px var(--gk-line); }
.gig-art { position: absolute; inset: 0; filter: blur(calc((1 - var(--p)) * 34px)) saturate(calc(0.4 + var(--p) * 0.6)); transform: scale(calc(1.15 - var(--p) * 0.15)); transition: filter 0.3s linear, transform 0.3s linear; }
.gig-art > * { width: 100%; height: 100%; object-fit: cover; display: block; }
/* A field of dots that dissolves as the picture sharpens */
.gig-dots { position: absolute; inset: 0; background-image: radial-gradient(circle, rgb(255 255 255 / 0.55) 1px, transparent 1.6px); background-size: 9px 9px; opacity: calc((1 - var(--p)) * 0.9); mix-blend-mode: overlay; animation: gig-drift 6s linear infinite; transition: opacity 0.4s; }
@keyframes gig-drift { to { background-position: 18px 9px; } }
.gig-shine { position: absolute; inset: 0; opacity: 0; background: linear-gradient(110deg, transparent 35%, rgb(255 255 255 / 0.45) 50%, transparent 65%); background-size: 250% 100%; background-position: 120% 0; pointer-events: none; }
.gig[data-done] .gig-shine { animation: gig-shine 1s 0.1s var(--gk-out); }
@keyframes gig-shine { 0% { opacity: 1; background-position: 120% 0; } 100% { opacity: 1; background-position: -30% 0; } }
.gig[data-done] .gig-art { transition: filter 0.6s var(--gk-out), transform 0.8s var(--gk-out); }
.gig-hud { position: absolute; inset: 0; display: grid; place-items: center; }
.gig-ring { --r: calc(var(--p) * 360deg); display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; color: #fff; background: radial-gradient(closest-side, rgb(16 16 20 / 0.55) 80%, transparent 82%), conic-gradient(#fff var(--r), rgb(255 255 255 / 0.22) 0); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }
.gig-ring b { font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; }
.gig-cancel { position: absolute; top: 10px; right: 10px; display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 50%; color: #fff; background: rgb(0 0 0 / 0.35); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); cursor: pointer; }
.gig-cap { position: absolute; left: 10px; right: 10px; bottom: 10px; padding: 8px 12px; border-radius: 12px; font-size: 13px; color: #fff; background: rgb(0 0 0 / 0.32); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px); text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ---------- Research ---------- */
.grs { display: flex; flex-direction: column; gap: 12px; padding: 14px 16px 16px; border-radius: 18px; color: var(--glass-fg); background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 10px 30px -22px rgb(0 0 0 / 0.4); text-align: left; }
.grs-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.grs-badge { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 9px 0 7px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--gk-c); background: color-mix(in srgb, var(--gk-c) 12%, transparent); }
[data-glass-tint="ink"] .grs-badge { color: var(--glass-fg); background: var(--gk-soft); }
.grs-head .grs-badge { margin-right: auto; }
.grs-title { order: 3; flex-basis: 100%; min-width: 0; font-size: 15px; font-weight: 600; line-height: 1.3; }
.grs-stop { display: grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 50%; color: var(--glass-on-tint, #fff); background: var(--glass-fg); cursor: pointer; transition: scale 0.3s var(--gk-spring); }
.grs-stop:active { scale: 0.88; }
.grs-steps { display: flex; flex-direction: column; gap: 7px; margin: 0; padding: 0; list-style: none; font-size: 13.5px; }
.grs-steps li { display: flex; align-items: flex-start; gap: 10px; color: var(--gk-mute); animation: gk-rise 0.4s calc(var(--i) * 60ms) var(--gk-out) backwards; transition: color 0.3s; }
.grs-steps li[data-s="active"], .grs-steps li[data-s="done"] { color: var(--glass-fg); }
.grs-dot { display: grid; place-items: center; flex: none; width: 16px; height: 16px; margin-top: 2px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px rgb(var(--glass-shadow) / 0.22); }
.grs-steps li[data-s="done"] .grs-dot { color: #fff; background: var(--gk-c); box-shadow: none; animation: gk-pop 0.35s var(--gk-spring); }
[data-glass-tint="ink"] .grs-steps li[data-s="done"] .grs-dot { color: var(--glass-on-tint); background: var(--glass-tint); }
.grs-dot i { width: 10px; height: 10px; border-radius: 50%; border: 1.6px solid color-mix(in srgb, var(--gk-c) 25%, transparent); border-top-color: var(--gk-c); animation: gk-spin 0.75s linear infinite; }
.grs-steps li[data-s="active"] .grs-dot { box-shadow: none; }
.grs-live { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; padding: 10px 12px; border-radius: 12px; font-size: 13px; background: var(--gk-soft); }
.grs-live .gak-fav { animation: gk-pop 0.4s var(--gk-spring) backwards; }
.grs-count b { display: inline-block; font-variant-numeric: tabular-nums; animation: gk-rise 0.3s var(--gk-out); }
.grs-now { flex-basis: 100%; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--gk-mute); animation: gk-rise 0.4s var(--gk-out); }
.grs-now em { font-style: normal; color: var(--glass-fg); }
.grs-bar { height: 4px; border-radius: 4px; overflow: hidden; background: var(--gk-soft); }
.grs-bar i { display: block; height: 100%; border-radius: inherit; background: var(--gk-c); transition: width 0.6s var(--gk-out); background-image: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.5), transparent); background-size: 60px 100%; background-repeat: no-repeat; animation: grs-run 1.4s linear infinite; background-color: var(--gk-c); }
@keyframes grs-run { from { background-position: -60px 0; } to { background-position: 400px 0; } }
.grs[data-status="stopped"] .grs-bar i { animation: none; opacity: 0.5; }
.grs-done { flex-direction: row; align-items: center; gap: 12px; width: 100%; border: 0; font: inherit; cursor: pointer; animation: gk-rise 0.5s var(--gk-out); transition: box-shadow 0.2s, translate 0.35s var(--gk-spring); }
.grs-done:hover { translate: 0 -1px; box-shadow: 0 0 0 1px rgb(var(--glass-shadow) / 0.16), 0 14px 30px -18px rgb(0 0 0 / 0.4); }
.grs-art { display: grid; place-items: center; flex: none; width: 44px; height: 52px; border-radius: 8px; color: var(--gk-c); background: color-mix(in srgb, var(--gk-c) 12%, transparent); }
[data-glass-tint="ink"] .grs-art { color: var(--glass-fg); background: var(--gk-soft); }
.grs-sum { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 0; }
.grs-sum strong { font-size: 14.5px; }
.grs-sum > span { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--gk-mute); }
.grs-open { flex: none; padding: 6px 12px; border-radius: 99px; font-size: 13px; font-weight: 500; background: var(--gk-soft); }

/* ---------- Composer ---------- */
.gkc { position: relative; display: flex; flex-direction: column; gap: 6px; padding: 10px; border-radius: 24px; color: var(--glass-fg); background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 12px 32px -20px rgb(0 0 0 / 0.35); transition: box-shadow 0.2s; }
.gkc:focus-within { box-shadow: 0 0 0 1px rgb(var(--glass-shadow) / 0.2), 0 0 0 4px color-mix(in srgb, var(--gk-c) 14%, transparent), 0 12px 32px -20px rgb(0 0 0 / 0.35); }
.gkc-files { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; padding: 2px; }
.gkc-file { position: relative; display: flex; align-items: center; gap: 9px; flex: none; max-width: 220px; height: 48px; padding: 6px 30px 6px 6px; border-radius: 14px; background: var(--gk-soft); animation: gk-rise 0.35s var(--gk-out); }
.gkc-file[data-kind="image"] { padding-right: 6px; width: 48px; }
.gkc-file[data-kind="image"] .gkc-fname { display: none; }
.gkc-thumb { width: 36px; height: 36px; border-radius: 9px; background-size: cover; }
.gkc-ficon { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 9px; color: #fff; background: #e5484d; }
.gkc-fname { display: flex; flex-direction: column; min-width: 0; font-size: 12.5px; line-height: 1.25; }
.gkc-fname b { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-weight: 600; }
.gkc-fname em { font-style: normal; color: var(--gk-mute); font-variant-numeric: tabular-nums; }
.gkc-up { --p: 0; position: absolute; left: 10px; top: 10px; width: 28px; height: 28px; border-radius: 50%; background: radial-gradient(closest-side, rgb(0 0 0 / 0.35) 70%, transparent 72%), conic-gradient(#fff calc(var(--p) * 360deg), rgb(255 255 255 / 0.3) 0); }
.gkc-x { position: absolute; top: -5px; right: -5px; display: grid; place-items: center; width: 20px; height: 20px; padding: 0; border: 0; border-radius: 50%; color: var(--gk-s); background: var(--glass-fg); box-shadow: 0 0 0 2px var(--gk-s); cursor: pointer; opacity: 0; transition: opacity 0.15s, scale 0.3s var(--gk-spring); }
.gkc-file:hover .gkc-x, .gkc-x:focus-visible { opacity: 1; }
@media (hover: none) { .gkc-x { opacity: 1; } }
.gkc-input { width: 100%; min-height: 26px; max-height: 200px; padding: 6px 8px; border: 0; resize: none; font: 400 15.5px/1.5 var(--font, inherit); color: var(--glass-fg); background: none; outline: none; }
.gkc-input::placeholder { color: rgb(var(--glass-shadow) / 0.45); }
.gkc-bar { display: flex; align-items: center; gap: 6px; }
.gkc-grow { flex: 1; }
.gkc-plus-wrap { position: relative; }
.gkc-round { display: grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; color: var(--glass-fg); background: none; box-shadow: inset 0 0 0 1px var(--gk-line); cursor: pointer; transition: background-color 0.15s, rotate 0.35s var(--gk-spring); }
.gkc-round:hover { background: var(--gk-soft); }
.gkc-round[data-on] { rotate: 45deg; background: var(--gk-soft); }
.gkc-menu { position: absolute; z-index: 40; left: 0; bottom: calc(100% + 8px); display: flex; flex-direction: column; min-width: 230px; padding: 6px; border-radius: 16px; background: var(--gk-s); box-shadow: 0 0 0 1px var(--gk-line), 0 20px 44px -18px rgb(0 0 0 / 0.35); transform-origin: bottom left; animation: gmp-in 0.3s var(--gk-spring); }
.gkc-menu button { display: flex; align-items: center; gap: 10px; height: 38px; padding: 0 10px; border: 0; border-radius: 10px; font: 500 14px var(--font, inherit); color: var(--glass-fg); background: none; cursor: pointer; text-align: left; }
.gkc-menu button:hover, .gkc-menu button:focus-visible { background: var(--gk-soft); outline: none; }
.gkc-menu svg { flex: none; width: 17px; height: 17px; color: var(--gk-mute); }
.gkc-switch { position: relative; width: 30px; height: 18px; margin-left: auto; border-radius: 99px; background: rgb(var(--glass-shadow) / 0.18); transition: background-color 0.2s; }
.gkc-switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgb(0 0 0 / 0.25); transition: translate 0.3s var(--gk-spring); }
.gkc-switch[data-on] { background: var(--gk-c); }
.gkc-switch[data-on]::after { translate: 12px 0; }
.gkc-mode { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 4px 0 10px; border-radius: 99px; font-size: 13px; font-weight: 500; color: var(--gk-c); background: color-mix(in srgb, var(--gk-c) 12%, transparent); animation: gk-pop 0.35s var(--gk-spring); }
[data-glass-tint="ink"] .gkc-mode { color: var(--glass-fg); background: var(--gk-soft); }
.gkc-mode svg { width: 14px; height: 14px; }
.gkc-mode button { display: grid; place-items: center; width: 22px; height: 22px; padding: 0; border: 0; border-radius: 50%; color: inherit; background: none; cursor: pointer; }
.gkc-mode button:hover { background: color-mix(in srgb, currentColor 14%, transparent); }
.gkc-send { display: grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; color: var(--glass-on-tint, #fff); background: var(--glass-tint, #111); cursor: pointer; transition: opacity 0.2s, scale 0.3s var(--gk-spring), background-color 0.2s; }
.gkc-send:disabled { opacity: 0.3; cursor: default; }
.gkc-send:active:not(:disabled) { scale: 0.88; }
.gkc-send[data-stop] { color: var(--gk-s); background: var(--glass-fg); animation: gk-pop 0.3s var(--gk-spring); }
.gkc-bar .gmp-chip { height: 34px; background: none; }
.gkc-bar .gmp-chip:hover, .gkc-bar .gmp[data-open] .gmp-chip { background: var(--gk-soft); }

@media (prefers-reduced-motion: reduce) {
  .gmp *, .gsta *, .gct *, .gma *, .gig *, .grs *, .grs, .gkc * { animation: none !important; transition: none !important; }
}

/* ---------- Phones: menus open as sheets from the bottom; small buttons get bigger touch areas ---------- */
@keyframes g-sheet-up { from { translate: 0 110%; } }
@media (max-width: 640px) {
  :is(.gmp-pop, .gkc-menu, .gct-card) { position: fixed !important; left: 8px !important; right: 8px !important; bottom: calc(8px + env(safe-area-inset-bottom)) !important; top: auto !important; width: auto !important; min-width: 0 !important; max-width: none !important; max-height: 72vh !important; overflow: auto !important; transform: none !important; z-index: 1000 !important; margin: 0 !important; padding-top: 22px !important; border-radius: 26px !important; box-shadow: 0 0 0 100vmax rgb(10 10 14 / 0.38), 0 -10px 40px -10px rgb(0 0 0 / 0.35) !important; animation: g-sheet-up 0.45s cubic-bezier(0.3, 1.4, 0.5, 1) !important; }
  :is(.gmp-pop, .gkc-menu, .gct-card)::before { content: ""; position: absolute; top: 8px; left: 50%; width: 38px; height: 5px; margin-left: -19px; border-radius: 9px; background: rgb(128 128 140 / 0.35); }
}
@media (pointer: coarse) {
  :is(.gma-sm, .grs-stop, .gkc-mode button) { position: relative; }
  :is(.gma-sm, .grs-stop, .gkc-mode button, .gkc-x)::after { content: ""; position: absolute; inset: -9px; }
}
